CREATE POLICY qualification_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id = 'qualifications' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY qualification_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id = 'qualifications' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY qualification_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id = 'qualifications' AND (storage.foldername(name))[1] = auth.uid()::text);